using System.Diagnostics.CodeAnalysis;

namespace VertexBPMN.Portal;

/// <summary>
/// Public marker type for the portal host used by <c>WebApplicationFactory</c> in the
/// test project. The actual host entry point is generated by the top-level statements
/// in <c>Program.cs</c>; this standalone type lets tests boot the host by reflecting on
/// the entry assembly (mirrors the API project's public Program marker).
/// </summary>
[SuppressMessage("Design", "CA1515", Justification = "Public marker type required for WebApplicationFactory<VertexBPMN.Portal.Program> in the test project.")]
[SuppressMessage("Design", "MA0048", Justification = "Public marker type deliberately named to match the host entry point for WebApplicationFactory bootstrapping.")]
public sealed class Program;
